\centering
\small
\begin{tabular}{@{}llrrrc@{}}
\toprule
\textbf{Task} & \textbf{Dom.} & \textbf{SG} & \textbf{Int.} & $\boldsymbol{\Delta}$ & \textbf{Sig.} \\
