\centering
\small
\begin{tabular}{@{}llrrc@{}}
\toprule
\textbf{Train} & \textbf{Eval} & \textbf{Score} & \textbf{R-Acc\%} & $\boldsymbol{\Delta}$ \textbf{vs.\ full} \\
\midrule
